function vpIcon(name, size = 20) {
  const svg = svgs[name];
  if (!svg) throw new Error(`Unknown Vitamin Play icon: ${name}`);
  return svg.replace(/width="24" height="24"/, `width="${size}" height="${size}"`).replace("<svg ", '<svg class="vp-icon" ');
}
module.exports = { vpIcon, vitaminIconNames: Object.keys(svgs) };
